// scripts/verify-seed.ts
// The script has been generated by Copilot to verify the seed data integrity and distribution.
// Reasoning: Time restrictions prevent me from writing this from scratch.

import { PrismaClient } from "../src/generated/prisma";

const prisma = new PrismaClient();

async function verifySeed() {
  console.log("🔍 Verifying seed data...\n");

  try {
    // 1. Basic counts
    console.log("📊 DATA COUNTS:");
    const [companies, branches, jobs, applicants, templates, submissions, answers] = await Promise.all([
      prisma.company.count(),
      prisma.branch.count(), 
      prisma.job.count(),
      prisma.applicant.count(),
      prisma.assessmentTemplate.count(),
      prisma.submission.count(),
      prisma.submissionAnswer.count()
    ]);

    console.log(`  Companies: ${companies}`);
    console.log(`  Branches: ${branches}`);
    console.log(`  Jobs: ${jobs}`);
    console.log(`  Applicants: ${applicants}`);
    console.log(`  Templates: ${templates}`);
    console.log(`  Submissions: ${submissions}`);
    console.log(`  Answers: ${answers}\n`);

    // 2. Company names
    console.log("🏢 COMPANIES:");
    const companiesData = await prisma.company.findMany({ 
      select: { name: true, _count: { select: { branches: true, jobs: true } } } 
    });
    companiesData.forEach(c => 
      console.log(`  ${c.name} (${c._count.branches} branches, ${c._count.jobs} jobs)`)
    );

    // 3. Assessment templates
    console.log("\n📝 ASSESSMENT TEMPLATES:");
    const templatesData = await prisma.assessmentTemplate.findMany({
      select: { 
        title: true, 
        profileKey: true,
        _count: { select: { items: true, jobs: true, submissions: true } }
      }
    });
    templatesData.forEach(t => 
      console.log(`  ${t.title} (${t.profileKey}) - ${t._count.items} items, ${t._count.jobs} jobs, ${t._count.submissions} submissions`)
    );

    // 4. Geographic distribution
    console.log("\n🌍 CITY DISTRIBUTION:");
    const cityStats = await prisma.applicant.groupBy({
      by: ['city'],
      _count: { city: true },
      orderBy: { _count: { city: 'desc' } },
      take: 10
    });
    cityStats.forEach(c => console.log(`  ${c.city}: ${c._count.city} applicants`));

    // 5. Assessment coverage
    const applicantsWithSubmissions = await prisma.applicant.count({
      where: { submissions: { some: {} } }
    });
    const coveragePercent = ((applicantsWithSubmissions / applicants) * 100).toFixed(1);
    console.log(`\n📈 ASSESSMENT COVERAGE: ${applicantsWithSubmissions}/${applicants} (${coveragePercent}%)`);

    // 6. Scoring distribution
    console.log("\n🎯 SCORING SAMPLE:");
    const sampleSubmissions = await prisma.submission.findMany({
      take: 5,
      include: {
        applicant: { select: { name: true } },
        template: { select: { title: true } },
        answers: { select: { isCorrect: true, itemWeight: true } }
      }
    });

    sampleSubmissions.forEach(s => {
      const totalScore = s.answers.reduce((sum, a) => 
        sum + (a.isCorrect ? a.itemWeight : 0), 0
      );
      const maxScore = s.answers.reduce((sum, a) => sum + a.itemWeight, 0);
      console.log(`  ${s.applicant.name}: ${totalScore}/${maxScore} on ${s.template.title}`);
    });

    // 7. Data integrity checks
    console.log("\n✅ INTEGRITY CHECKS:");
    
    // Check for missing relationships (should be 0 due to FK constraints)
    const jobsWithoutTemplate = await prisma.job.count({
      where: { templateId: null }
    });
    
    const totalBranches2 = await prisma.branch.count(); // All branches should have companyId
    const totalSubmissions = await prisma.submission.count(); // All submissions should have both IDs

    console.log(`  Jobs without templates: ${jobsWithoutTemplate}`);
    console.log(`  Total branches (all should have companyId): ${totalBranches2}`);
    console.log(`  Total submissions (all should have valid IDs): ${totalSubmissions}`);

    // Check question weights
    const weightDistribution = await prisma.assessmentItem.groupBy({
      by: ['weight'],
      _count: { weight: true },
      orderBy: { weight: 'asc' }
    });
    console.log(`  Question weights: ${weightDistribution.map(w => `${w.weight}:${w._count.weight}`).join(', ')}`);

    console.log("\n🎉 Seed verification complete!");

  } catch (error) {
    console.error("❌ Verification failed:", error);
  } finally {
    await prisma.$disconnect();
  }
}

verifySeed();